from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')

# Access the sheets
sheet1 = wb['Sheet1']
sheet2 = wb['Sheet2']

# Create a dictionary to map NAME to 100 value from Sheet2
name_to_100 = {}
for row in sheet2.iter_rows(min_row=2, min_col=7, max_col=9):
    name = row[0].value
    if name:
        name_to_100[name] = row[2].value

# Update Sheet1 with computed values
for row in sheet1.iter_rows(min_row=2, min_col=6, max_col=8):
    name_cell = row[0]
    if name_cell.value:
        name = name_cell.value
        # Trim the name to ensure consistency
        name = name.strip()
        # Look up the value in the dictionary
        if name in name_to_100:
            row[1].value = name_to_100[name]
        else:
            row[1].value = '#N/A'

# Format cells G2:I7 to text and left align
for cell in sheet1['G2':'I7']:
    for c in cell:
        c.number_format = '@'
        c.alignment = {'horizontal': 'left'}

# Save the workbook
wb.save('output.xlsx')
