from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Clear values below row 7 in columns C and D
for row in range(8, ws.max_row + 1):
    ws.cell(row=row, column=3, value=None)
    ws.cell(row=row, column=4, value=None)

# Define the range for the data to process
date_column = 'A'
primary_header_row = 2
secondary_header_row = 3
data_start_row = 4
data_end_row = 7
data_start_col = 18  # Column BE is the 19th column (index 18)
data_end_col = 39    # Column BR is the 40th column (index 39)

# Create a dictionary to map dates to their corresponding row indices
date_to_row = {}
for row in range(3, ws.max_row + 1):
    date = ws[f'{date_column}{row}'].value
    if date:
        date_to_row[date] = row

# Create a dictionary to map secondary headers to their column indices
secondary_header_to_col = {}
for col in range(data_start_col, data_end_col + 1):
    header = ws[f'{get_column_letter(col)}{secondary_header_row}'].value
    if header:
        secondary_header_to_col[header] = col

# Compute values for cells C4:D7
for row in range(data_start_row, data_end_row + 1):
    date = ws[f'{date_column}{row}'].value
    if date in date_to_row:
        date_row = date_to_row[date]
        for col in range(data_start_col, data_end_col + 1):
            header = ws[f'{get_column_letter(col)}{secondary_header_row}'].value
            if header:
                col_index = secondary_header_to_col[header]
                value = ws[f'{get_column_letter(col_index)}{date_row}'].value
                if value is not None:
                    ws[f'C{row}'].value = int(value)
                    break
                else:
                    ws[f'C{row}'].value = '-'
    else:
        ws[f'C{row}'].value = '-'

# Write the computed values to D4:D7
for row in range(data_start_row, data_end_row + 1):
    date = ws[f'{date_column}{row}'].value
    if date in date_to_row:
        date_row = date_to_row[date]
        for col in range(data_start_col, data_end_col + 1):
            header = ws[f'{get_column_letter(col)}{secondary_header_row}'].value
            if header:
                col_index = secondary_header_to_col[header]
                value = ws[f'{get_column_letter(col_index)}{date_row}'].value
                if value is not None:
                    ws[f'D{row}'].value = int(value)
                    break
                else:
                    ws[f'D{row}'].value = '-'
    else:
        ws[f'D{row}'].value = '-'

# Save the workbook
wb.save('output.xlsx')
